#!/data/data/com.termux/files/usr/bin/bash
# module_007: dual_license (license)
# generated by binmix-base
set -u

# ─── BINMIX GUARD ───
BINMIX_LIMIT=$((65*1024*1024))
SANDBOX="$HOME/CYBRA/sandbox"
mkdir -p "$SANDBOX"/{bin,tmp,keep,trash} 2>/dev/null
SIZE=$(du -sb "$SANDBOX" 2>/dev/null | awk '{print $1}' || echo 0)
if [ "${SIZE:-0}" -ge "$BINMIX_LIMIT" ]; then
  rm -rf "$SANDBOX/trash/"* "$SANDBOX/tmp/"* 2>/dev/null
  [ -x "$SANDBOX/sandbox_cleanup.sh" ] && "$SANDBOX/sandbox_cleanup.sh" >/dev/null 2>&1
fi
# ─── END GUARD ───

CYBRA="${CYBRA:-$HOME/CYBRA}"; cd "$CYBRA" 2>/dev/null || exit 1
LOG="$CYBRA/logs/module_007.log"; mkdir -p "$(dirname "$LOG")"
log() { echo "[$(date -u +%FT%TZ)] $*" >> "$LOG"; }
trap 'log "ERR line $LINENO"' ERR
ACTION="${1:-help}"; shift $(( $# > 0 ? 1 : 0 ))
KEY="cybra:license:data"
log "START dual_license action=$ACTION"

# ─── EXTENSION HOOK (binmix-mixin додає сюди) ───
case "$ACTION" in
# <<<BINMIX_EXTENSIONS>>>
  add|create|register)
    if [ $# -lt 1 ]; then echo "usage: $0 add <name> [value]"; exit 1; fi
    VAL="${2:-$(date +%s)}"
    redis-cli hset "$KEY" "$1" "$VAL" >/dev/null || { echo "FAIL"; exit 1; }
    echo "OK: $1 = $VAL"
    ;;
  list|status|show)
    N=$(redis-cli hlen "$KEY" 2>/dev/null || echo 0)
    echo "  items: $N"
    if [ "$N" -gt 0 ]; then
      redis-cli hgetall "$KEY" | paste - - | head -20 | sed 's/^/  /'
    fi
    ;;
  delete|remove|rm)
    if [ $# -lt 1 ]; then echo "usage: $0 delete <name>"; exit 1; fi
    redis-cli hdel "$KEY" "$1" >/dev/null || exit 1
    echo "OK: deleted $1"
    ;;

  help|*)
    echo "==== module_007: dual_license ===="
    echo "  version: base"
    echo "  actions: help"
    echo "  hint: binmix-mixin докрутить add/list/delete поступово"
    ;;
esac
rc=$?; log "DONE rc=$rc"; exit $rc
